@lru_cache(maxsize=1)
def recorded_base():
    raw = zlib.decompress(base64.b85decode(RECORDED))
    assert hashlib.sha256(raw).hexdigest() == FIXTURE_SHA256
    value = json.loads(raw)
    first, last = value['failed']['started_at'], value['failed']['entry_input_finished_at']
    value['failed']['raw_entry_packets'] = deepcopy([r for r in value['rows'] if first <= r['time'] <= last])
    value['failed']['raw_entry_events'] = deepcopy([e for e in value['events'] if first <= e['time'] <= last])
    return value


def recorded():
    return deepcopy(recorded_base())


def proof(value):
    return stopped.stopped_history(*(value[k] for k in ('rows', 'events', 'ready', 'failed',
        'observation', 'before_precision')), audit_until=value['audit_until'])


def append_row(value, row):
    row = {**row, 'session': value['ready']['native_session']}
    value['rows'].append(row)
    native = row['direction'] in ('from_native', 'to_native')
    value['events'].append({'session': row['session'] if native else 'b47a0541',
        'time': row['time'] - .00001, 'name': row['name'], 'direction': row['direction'],
        'bytes': len(bytes.fromhex(row['body'])), 'event': 'native_packet' if native else 'modern_packet'})


def replace_body_and_metadata(value, row, raw):
    old_size = len(bytes.fromhex(row['body']))
    candidates = [e for e in value['events'] if e.get('event') == 'native_packet' and
        (e.get('name'), e.get('direction'), e.get('bytes')) == (row['name'], row['direction'], old_size) and
        0 <= row['time'] - e['time'] < .1]
    event = max(candidates, key=lambda e: e['time'])
    event['bytes'] = len(raw)
    row['body'] = raw.hex()


def packed_native(identity):
    octets = struct.pack('<Q', identity)
    return bytes([sum(bool(v) << i for i, v in enumerate(octets))]) + bytes(v for v in octets if v)


def test_actual_complete_stopped_history_is_excluded_and_serializable_without_io():
    value = recorded()
    assert SOURCE_SHA256['failed'] == stopped.FAILED_SHA256
    assert SOURCE_SHA256['observation'] == '81083e598e9b542f715e1ae69e32242d2008ed296f03fe1c9f9c74b2bc45a68d'
    result = proof(value)
    assert (result['source_packet_count'], result['source_event_count']) == (5444, 6731)
    assert (result['original_prefix_packet_count'], result['original_prefix_event_count']) == (1202, 1493)
    assert result['original_prefix_end'] == 1791431448.852425
    assert result['until'] == 1791431566.305878
    assert result['last_wire_at'] == 1791431566.2817762  # Modern delivered object packet.
    assert result['last_native_wire_at'] == 1791431566.2811675
    assert result['audit_until'] == 1791432514.2053306
    assert result['saved_logout_time'] == 1791431626
    assert result['socket_expiry_seconds'] == 60
    assert result['normal_logout_input_sent'] is False
    assert result['qualification_excluded'] is True and result['operations_admitted'] == 0
    assert result['observed_owned_game_pid'] == 3811373 and result['game_start_ticks_retained'] is False
    assert result['native_state']['pose'] == {'stand': 0, 'sheath': 0}
    assert result['native_state']['afk'] is False
    assert result['rest'] == {'native_login_second': 1791431430, 'offline_seconds': 8481,
        'before_float32_bits': 'bfc05542', 'after_float32_bits': '6b985b42',
        'exact_after': 54.89884567260742, 'rest_threshold': 54, 'rounded_baseline_reconstruction': False}
    assert result['metadata_only_delivered_movement_count'] == 966
    assert result['metadata_only_delivered_movement_bodies_retained'] is False
    assert result['metadata_only_delivered_movement_identity_proved'] is False
    assert result['routine']['latency'] == {'realm_occurrences': 5, 'physical_occurrences': 5, 'bodies_retained': False}
    assert result['routine']['time_sync_occurrences'] == 24
    assert result['routine']['quest_status_occurrences'] == 26
    assert len(json.dumps(result)) < 40000  # No NPC arrays or six-actor snapshot duplication.
    assert json.loads(json.dumps(result, allow_nan=False)) == result


@pytest.mark.parametrize('fault', ['raw_prefix_missing', 'event_prefix_missing', 'raw_prefix_order',
    'event_prefix_order', 'coedited_prefix', 'raw_duplicate', 'event_duplicate', 'before_interval',
    'after_interval', 'null_time', 'foreign_actor', 'foreign_login'])
def test_complete_original_prefix_membership_order_and_attribution_are_immutable(fault):
    value = recorded()
    if fault == 'raw_prefix_missing': value['rows'].pop(0)
    elif fault == 'event_prefix_missing': value['events'].pop(20)
    elif fault == 'raw_prefix_order': value['rows'][20], value['rows'][21] = value['rows'][21], value['rows'][20]
    elif fault == 'event_prefix_order': value['events'][20], value['events'][21] = value['events'][21], value['events'][20]
    elif fault == 'coedited_prefix':
        for array in (value['rows'], value['failed']['raw_entry_packets']):
            next(r for r in array if r['name'] == 'CMSG_REQUEST_RATED_PVP_INFO')['body'] += '00'
    elif fault == 'raw_duplicate': value['rows'].append(deepcopy(value['rows'][0]))
    elif fault == 'event_duplicate': value['events'].append(deepcopy(value['events'][0]))
    elif fault == 'before_interval': value['rows'].append({**value['rows'][0], 'time': value['ready']['started_at'] - .01})
    elif fault == 'after_interval': value['events'].append({**value['events'][0], 'time': value['audit_until'] + .01})
    elif fault == 'null_time': value['events'].append({'event': 'movement_forwarded', 'session': 'foreign', 'guid': 2, 'time': None})
    elif fault == 'foreign_actor': value['events'].append({'event': 'instance_authenticated', 'session': 'foreign', 'account_id': 2, 'time': value['audit_until'] - 1})
    else: append_row(value, {'time': value['failed']['finished_at'] + 1, 'name': 'CMSG_PLAYER_LOGIN', 'direction': 'from_client', 'body': '01a002040800a09f44'})
    with pytest.raises(RuntimeError): proof(value)


@pytest.mark.parametrize('name', ['CMSG_MOVE_HEARTBEAT', 'CMSG_MOVE_INIT_ACTIVE_MOVER_COMPLETE',
    'CMSG_STAND_STATE_CHANGE', 'CMSG_SET_SELECTION', 'CMSG_ATTACK_SWING', 'CMSG_SET_ACTION_BUTTON',
    'CMSG_CAST_SPELL', 'CMSG_USE_ITEM', 'CMSG_SWAP_INV_ITEM', 'CMSG_PET_ACTION', 'CMSG_LOGOUT_REQUEST',
    'CMSG_CHAT_MESSAGE_AFK'])
@pytest.mark.parametrize('direction', ['from_client', 'to_native'])
def test_no_post_entry_gameplay_or_normal_logout_can_be_added(name, direction):
    value = recorded()
    append_row(value, {'time': value['failed']['finished_at'] + 1, 'name': name, 'direction': direction, 'body': '00'})
    with pytest.raises(RuntimeError): proof(value)


@pytest.mark.parametrize('fault', ['owner_health', 'owner_stand', 'owner_afk', 'inventory_slot', 'item_count',
    'item_durability', 'recreate', 'remove_item', 'destroy_owner', 'combat_owner', 'combat_trailing'])
def test_every_native_owner_item_field_and_retained_combat_body_remains_bound(fault):
    from tools.client_compatibility.world.tests.test_item_actionbar_contract import native_packet
    value = recorded()
    timestamp = value['failed']['finished_at'] + 1
    if fault in ('owner_health', 'owner_stand', 'owner_afk', 'inventory_slot', 'item_count', 'item_durability'):
        fields = {'owner_health': {'UNIT_FIELD_HEALTH': 59}, 'owner_stand': {'UNIT_FIELD_BYTES_1': 1},
            'owner_afk': {'PLAYER_FLAGS': 2}, 'inventory_slot': {'PLAYER_FIELD_INV_SLOT_HEAD': 1},
            'item_count': {'ITEM_FIELD_STACK_COUNT': 2}, 'item_durability': {'ITEM_FIELD_DURABILITY': 54}}[fault]
        row = native_packet({stopped.INDEX[k]: v for k, v in fields.items()}, creation=False,
            guid=((0x4000 << 48) | 33) if fault.startswith('item_') else 2, time=timestamp)
        append_row(value, row)
    elif fault == 'recreate':
        original = next(r for r in value['rows'] if r['name'] == 'SMSG_UPDATE_OBJECT' and r['direction'] == 'from_native')
        append_row(value, {**original, 'time': timestamp})
    elif fault == 'remove_item':
        raw = Writer().pack('HI', 0, 1).pack('BI', 3, 1).raw(packed_native((0x4000 << 48) | 33)).finish()
        append_row(value, {'time': timestamp, 'name': 'SMSG_UPDATE_OBJECT', 'direction': 'from_native', 'body': raw.hex()})
    elif fault == 'destroy_owner':
        append_row(value, {'time': timestamp, 'name': 'SMSG_DESTROY_OBJECT', 'direction': 'from_native', 'body': struct.pack('<QB', 2, 0).hex()})
    else:
        row = next(r for r in value['rows'] if r['name'] == 'SMSG_ATTACKER_STATE_UPDATE' and r['time'] > value['failed']['entry_input_finished_at'])
        raw = bytes.fromhex(row['body'])
        if fault == 'combat_owner':
            size = 1 + raw[4].bit_count()
            raw = raw[:4] + packed_native(2) + raw[4 + size:]
        else: raw += b'\0'
        replace_body_and_metadata(value, row, raw)
    with pytest.raises(RuntimeError): proof(value)


@pytest.mark.parametrize('fault', ['missing_eof', 'missing_cancel', 'wrong_boundary_session', 'wrong_error',
    'late_cancel', 'post_close_packet', 'tutorial_missing_drop', 'tutorial_forwarded', 'ping_incomplete',
    'server_time_forwarded', 'routine_body', 'routine_missing_raw', 'normal_logout_response'])
def test_routine_occurrences_and_socket_expiry_teardown_cannot_hide_another_effect(fault):
    value = recorded()
    eof = next(e for e in value['events'] if e['event'] == 'world_connection_closed')
    cancel = next(e for e in value['events'] if e['event'] == 'native_stream_closed')
    if fault == 'missing_eof': value['events'].remove(eof)
    elif fault == 'missing_cancel': value['events'].remove(cancel)
    elif fault == 'wrong_boundary_session': eof['session'] = 'b47a0541'
    elif fault == 'wrong_error': eof['error'] = 'clean normal logout'
    elif fault == 'late_cancel': cancel['time'] += 2
    elif fault == 'post_close_packet':
        row = next(r for r in value['rows'] if r['name'] == 'SMSG_UPDATE_OBJECT' and r['time'] > value['failed']['entry_input_finished_at'])
        append_row(value, {**row, 'time': cancel['time'] + 1})
    elif fault == 'tutorial_missing_drop':
        value['events'].remove(next(e for e in value['events'] if e.get('name') == 'CMSG_TUTORIAL' and e['time'] > value['failed']['entry_input_finished_at'] and e['event'] == 'unmapped_client_packet'))
    elif fault == 'tutorial_forwarded':
        event = next(e for e in value['events'] if e.get('name') == 'CMSG_TUTORIAL' and e['time'] > value['failed']['entry_input_finished_at'])
        value['events'].append({**event, 'event': 'native_packet', 'direction': 'to_native', 'time': event['time'] + .0001})
    elif fault == 'ping_incomplete':
        value['events'].remove(next(e for e in value['events'] if e.get('name') == 'SMSG_PONG' and e['time'] > value['failed']['entry_input_finished_at']))
    elif fault == 'server_time_forwarded':
        append_row(value, {'time': value['failed']['finished_at'] + 1, 'name': 'CMSG_SERVER_TIME_OFFSET_REQUEST', 'direction': 'to_native', 'body': ''})
    elif fault == 'routine_body':
        row = next(r for r in value['rows'] if r['name'] == 'CMSG_TIME_SYNC_RESP' and r['time'] > value['failed']['entry_input_finished_at'])
        row['body'] = 'ff' + row['body'][2:]
    elif fault == 'routine_missing_raw':
        value['rows'].remove(next(r for r in value['rows'] if r['name'] == 'SMSG_TIME_SYNC_REQ' and r['time'] > value['failed']['entry_input_finished_at']))
    else: append_row(value, {'time': value['failed']['finished_at'] + 1, 'name': 'SMSG_LOGOUT_RESPONSE', 'direction': 'from_native', 'body': '0000000000'})
    with pytest.raises(RuntimeError): proof(value)


@pytest.mark.parametrize('fault', ['dropped_cast', 'owner_update_without_body', 'root_without_body'])
def test_metadata_only_rows_cannot_hide_gameplay_or_an_owned_native_effect(fault):
    value = recorded()
    event = {'session': value['ready']['native_session'], 'time': value['failed']['finished_at'] + 1,
        'name': 'CMSG_CAST_SPELL', 'bytes': 12, 'event': 'unmapped_client_packet'}
    if fault != 'dropped_cast':
        event.update(name='SMSG_UPDATE_OBJECT' if fault == 'owner_update_without_body' else 'SMSG_MOVE_ROOT',
            direction='from_native', event='native_packet')
    value['events'].append(event)
    with pytest.raises(RuntimeError): proof(value)


@pytest.mark.parametrize('fault', ['false_stop_check', 'extra_stop_check', 'invented_ticks', 'wrong_pid',
    'float_pid', 'claimed_cleanup', 'qualified', 'wrong_runtime', 'wrong_failed_code', 'saved_spell',
    'sql_item_column', 'protected_actor', 'sql_health', 'logout_second', 'exact_bits', 'rounded_baseline',
    'after_query_snapshot', 'precision_query'])
def test_stopped_observation_preservation_and_exact_rest_are_source_owned(fault):
    value = recorded()
    observation = value['observation']
    if fault == 'false_stop_check': observation['checks']['bridge_lifetime'] = False
    elif fault == 'extra_stop_check': observation['checks']['invented_stop_started_at'] = True
    elif fault == 'invented_ticks': observation['game_start_ticks'] = '0001'
    elif fault == 'wrong_pid': observation['observed_owned_game_pid'] += 1
    elif fault == 'float_pid': observation['observed_owned_game_pid'] = float(observation['observed_owned_game_pid'])
    elif fault == 'claimed_cleanup': observation['normal_logout_input_sent'] = True
    elif fault == 'qualified': observation['operations_admitted'] = True
    elif fault == 'wrong_runtime': observation['runtime']['worldserver']['pid'] += 1
    elif fault == 'wrong_failed_code': value['failed']['code_commit'] = 'a' * 40
    elif fault == 'saved_spell': observation['after']['2']['saved']['spells'].append([100, 1, 0])
    elif fault == 'sql_item_column': observation['after']['2']['inventory'][-1][16] += 1
    elif fault == 'protected_actor': observation['after']['3']['native']['money'] += 1
    elif fault == 'sql_health': observation['after']['2']['native']['health'] -= 1
    elif fault == 'logout_second':
        for snapshot in (observation['after'], observation['exact_after_precision']['before'], observation['exact_after_precision']['after']):
            snapshot['2']['native']['logout_time'] += 1
        observation['exact_after_precision']['row']['logout_time'] += 1
    elif fault == 'exact_bits': observation['exact_after_precision']['row']['exact_rest_bonus_float32_bits'] = '00000000'
    elif fault == 'rounded_baseline': value['before_precision']['row']['exact_rest_bonus'] = 53.4382
    elif fault == 'after_query_snapshot': observation['exact_after_precision']['after']['2']['native']['latency'] += 1
    else: value['before_precision']['query'] += ' LIMIT 1'
    with pytest.raises(RuntimeError): proof(value)
